        @if ($testResult)
            <div class="space-y-4">
                <section class="rounded-xl border p-4" style="border-color:color-mix(in srgb,{{ $testResult['valid'] ? 'var(--theme-success-color)' : 'var(--theme-warning-color)' }} 35%,var(--theme-border-color));background:color-mix(in srgb,{{ $testResult['valid'] ? 'var(--theme-success-color)' : 'var(--theme-warning-color)' }} 8%,var(--theme-surface-base))"><div class="flex gap-3"><span class="grid h-9 w-9 shrink-0 place-items-center rounded-lg" style="background:var(--theme-surface-base);color:{{ $testResult['valid'] ? 'var(--theme-success-color)' : 'var(--theme-warning-color)' }}"><i class="fa-light {{ $testResult['valid'] ? 'fa-check' : 'fa-triangle-exclamation' }}"></i></span><div><strong>{{ $testResult['valid'] ? __('Graph structure is valid') : __('Graph needs attention') }}</strong><p class="mt-1 text-xs" style="color:var(--theme-muted-text-color)">{{ __('No external action was executed.') }}</p></div></div></section>
                @if (!empty($testResult['issues']))<ul class="grid gap-2 rounded-xl border p-4 text-xs" style="border-color:var(--theme-control-border-color,var(--theme-border-color))">@foreach($testResult['issues'] as $issue)<li><i class="fa-light fa-circle-xmark mr-2" style="color:var(--theme-danger-color)"></i>{{ $issue }}</li>@endforeach</ul>@endif
                @if (!empty($testResult['notices']))<div><p class="automation-panel-kicker">{{ __('Runtime readiness') }}</p><ul class="mt-2 grid gap-2">@foreach($testResult['notices'] as $notice)<li class="rounded-xl border p-3 text-xs leading-5" style="border-color:var(--theme-control-border-color,var(--theme-border-color));color:var(--theme-muted-text-color)"><i class="fa-light fa-plug-circle-exclamation mr-2" style="color:var(--theme-warning-color)"></i>{{ $notice }}</li>@endforeach</ul></div>@endif
                <div><p class="automation-panel-kicker">{{ __('Execution path') }}</p><ol class="mt-2 grid gap-2 sm:grid-cols-2">@foreach($testResult['steps'] as $index => $step)<li class="flex items-center gap-3 rounded-xl border p-3 text-xs" style="border-color:var(--theme-control-border-color,var(--theme-border-color))"><span class="grid h-7 w-7 shrink-0 place-items-center rounded-full text-[9px] font-black" style="background:color-mix(in srgb,var(--theme-accent) 12%,transparent);color:var(--theme-accent)">{{ $index + 1 }}</span><span class="font-bold">{{ $step['label'] }}</span></li>@endforeach</ol></div>
            </div>
        @endif
        <x-slot:footer><x-ui.button type="button" variant="outline" x-on:click="open=false">{{ __('Close') }}</x-ui.button></x-slot:footer>
    </x-ui.dialog>

