                requestDelete(node){this.pendingDeleteId=node.id;this.$nextTick(()=>document.getElementById('automation-node-delete-trigger')?.click())},confirmDelete(){if(!this.pendingDeleteId)return;this.nodes=this.nodes.filter(n=>n.id!==this.pendingDeleteId);this.edges=this.edges.filter(e=>e.from!==this.pendingDeleteId&&e.to!==this.pendingDeleteId);if(this.selectedId===this.pendingDeleteId)this.selectedId=null;this.pendingDeleteId=null;this.changed()},togglePin(node){node.pinned=!node.pinned;this.changed()},changed(){this.dirty=true;this.future=[];this.snapshot()},snapshot(force=true){const state=JSON.stringify({nodes:this.nodes,edges:this.edges});if(this.history.at(-1)!==state)this.history.push(state);if(this.history.length>60)this.history.shift();if(force)this.miniTick++},restore(state){const data=JSON.parse(state);this.nodes=data.nodes;this.edges=data.edges;this.selectedId=null;this.dirty=true;this.miniTick++},undo(){if(this.history.length<2)return;this.future.push(this.history.pop());this.restore(this.history.at(-1))},redo(){if(!this.future.length)return;const state=this.future.pop();this.history.push(state);this.restore(state)},
                bounds(){if(!this.nodes.length)return{l:1800,t:1300,r:2400,b:1800};return{l:Math.min(...this.nodes.map(n=>n.x)),t:Math.min(...this.nodes.map(n=>n.y)),r:Math.max(...this.nodes.map(n=>n.x+(this.nodeElement(n)?.offsetWidth||228))),b:Math.max(...this.nodes.map(n=>n.y+(this.nodeElement(n)?.offsetHeight||112)))}},center(smooth=false){const c=this.$refs.canvas;if(!c)return;const b=this.bounds();c.scrollTo({left:(b.l+b.r)/2*this.zoom-c.clientWidth/2,top:(b.t+b.b)/2*this.zoom-c.clientHeight/2,behavior:smooth?'smooth':'auto'});this.miniTick++},centerOn(node){const c=this.$refs.canvas;if(!c||!node)return;const element=this.nodeElement(node);c.scrollTo({left:(node.x+(element?.offsetWidth||228)/2)*this.zoom-c.clientWidth/2,top:(node.y+(element?.offsetHeight||112)/2)*this.zoom-c.clientHeight/2,behavior:'smooth'})},fit(){const c=this.$refs.canvas;if(!c)return;const b=this.bounds();this.setZoom(Math.min(1.15,Math.max(.15,Math.min((c.clientWidth-60)/(b.r-b.l),(c.clientHeight-120)/(b.b-b.t)))));this.$nextTick(()=>this.center())},setZoom(value,anchor=null){const c=this.$refs.canvas;if(!c)return;const previous=this.zoom,next=Math.max(.15,Math.min(1.4,Math.round(value*100)/100));if(next===previous)return;const x=anchor?.x??c.clientWidth/2,y=anchor?.y??c.clientHeight/2,worldX=(c.scrollLeft+x)/previous,worldY=(c.scrollTop+y)/previous;this.zoom=next;c.scrollLeft=worldX*next-x;c.scrollTop=worldY*next-y;this.miniTick++},miniNodeStyle(node){this.miniTick;return`left:${Math.max(0,Math.min(this.minimapWidth-32,node.x/this.stageWidth*this.minimapWidth))}px;top:${Math.max(0,Math.min(this.minimapHeight-16,node.y/this.stageHeight*this.minimapHeight))}px;--node-color:${this.meta(node.type).color}`},syncMinimap(){this.miniTick++},miniViewportStyle(){this.miniTick;const c=this.$refs.canvas;if(!c)return'display:none';const w=Math.max(16,Math.min(this.minimapWidth,c.clientWidth/(this.stageWidth*this.zoom)*this.minimapWidth)),h=Math.max(12,Math.min(this.minimapHeight,c.clientHeight/(this.