                async sync(){await this.$wire.set('flowCanvas',JSON.stringify({version:1,nodes:this.nodes,edges:this.edges}),false)},async testFlow(){await this.sync();await this.$wire.preview()},async saveFlow(publish){if(this.saving)return;this.saving=true;try{await this.sync();await this.$wire.saveGraph(JSON.stringify({version:1,nodes:this.nodes,edges:this.edges}),Boolean(publish))}catch(error){console.error(error);this.toast('error',@js(__('The workflow could not be saved. Review the validation result and try again.')))}finally{this.saving=false}},toast(type,message){window.dispatchEvent(new CustomEvent('app-toast',{detail:{type,title:@js(__('AI Workflows')),message}}))},onKeydown(event){if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='s'){event.preventDefault();this.saveFlow(false);return}if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='z'){event.preventDefault();event.shiftKey?this.redo():this.undo()}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='y'){event.preventDefault();this.redo()}if(!this.guided&&event.key==='Delete'&&this.selectedNode&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))this.requestDelete(this.selectedNode)}
